import CryptoKit
import XCTest
@testable import AnyDisplayProtocol

/// Reproduces every value in tools/vectors.json (generated by `anydisplay_ref.py vectors`).
final class VectorTests: XCTestCase {
    struct ModeVectors: Decodable {
        let psk, k_h2c, k_c2h, k_confirm, auth_h, auth_c, encrypted_ping_h2c_seq0: String
    }

    struct Vectors: Decodable {
        let client_private, host_private, client_pub, host_pub, client_nonce, host_nonce: String
        let hello_c_body, hello_h_body, reveal_body, transcript, ecdh_z, sas, ping_plaintext_body: String
        let mode1, mode2: ModeVectors
    }

    static let vectors: Vectors = {
        let url = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().appendingPathComponent("tools/vectors.json")
        return try! JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }()

    var v: Vectors { Self.vectors }

    func hex(_ s: String) -> Data { Data(hex: s)! }

    func keys() throws -> (client: P256.KeyAgreement.PrivateKey, host: P256.KeyAgreement.PrivateKey) {
        (try P256.KeyAgreement.PrivateKey(rawRepresentation: hex(v.client_private)),
         try P256.KeyAgreement.PrivateKey(rawRepresentation: hex(v.host_private)))
    }

    func helloC(clientPub: Data) -> HelloC {
        HelloC(deviceID: Data(0xA0..<0xB0), deviceName: "Phone", link: 1, authRequired: 1, clientPub: clientPub,
               clientCommit: AnyDisplayCrypto.sha256(hex(v.client_nonce)))
    }

    func helloH(hostPub: Data) -> HelloH {
        HelloH(hostID: Data(0xB0..<0xC0), hostName: "Mac", hostOS: "macOS", authMode: 1, hostPub: hostPub,
               hostNonce: hex(v.host_nonce))
    }

    func testPublicKeysAndNonces() throws {
        let (c, h) = try keys()
        XCTAssertEqual(c.publicKey.x963Representation.hex, v.client_pub)
        XCTAssertEqual(h.publicKey.x963Representation.hex, v.host_pub)
        XCTAssertEqual(Data(0..<32).hex, v.client_nonce)
        XCTAssertEqual(Data(32..<64).hex, v.host_nonce)
    }

    func testHelloBodiesTranscriptSAS() throws {
        let (c, h) = try keys()
        let hc = helloC(clientPub: c.publicKey.x963Representation).encode()
        let hh = helloH(hostPub: h.publicKey.x963Representation).encode()
        XCTAssertEqual(hc.hex, v.hello_c_body)
        XCTAssertEqual(hh.hex, v.hello_h_body)
        XCTAssertEqual(hex(v.client_nonce).hex, v.reveal_body)
        let t = AnyDisplayCrypto.transcript(helloC: hc, helloH: hh, reveal: hex(v.reveal_body))
        XCTAssertEqual(t.hex, v.transcript)
        XCTAssertEqual(AnyDisplayCrypto.sasString(transcript: t), v.sas)

        // Decoding the vector bodies yields the same fields back.
        let decoded = try HelloC(body: hex(v.hello_c_body))
        XCTAssertEqual(decoded.deviceName, "Phone")
        XCTAssertEqual(decoded.encode().hex, v.hello_c_body)
        XCTAssertEqual(try HelloH(body: hex(v.hello_h_body)).encode().hex, v.hello_h_body)
    }

    func testECDH() throws {
        let (c, h) = try keys()
        let z1 = try AnyDisplayCrypto.ecdh(privateKey: c, peerPublic: hex(v.host_pub))
        let z2 = try AnyDisplayCrypto.ecdh(privateKey: h, peerPublic: hex(v.client_pub))
        XCTAssertEqual(z1.hex, v.ecdh_z)
        XCTAssertEqual(z2.hex, v.ecdh_z)
    }

    func testPingPlaintext() {
        XCTAssertEqual(Ping(seq: 7, senderTimeUs: 123_456_789).encode().hex, v.ping_plaintext_body)
    }

    func testMode1() { check(v.mode1) }
    func testMode2() { check(v.mode2) }

    private func check(_ m: ModeVectors, file: StaticString = #filePath, line: UInt = #line) {
        let t = hex(v.transcript)
        XCTAssertEqual(hex(m.psk).count, m.psk.isEmpty ? 0 : 32)
        let keys = AnyDisplayCrypto.keySchedule(z: hex(v.ecdh_z), psk: hex(m.psk), transcript: t)
        XCTAssertEqual(keys.hostToClient.hex, m.k_h2c, file: file, line: line)
        XCTAssertEqual(keys.clientToHost.hex, m.k_c2h, file: file, line: line)
        XCTAssertEqual(keys.confirm.hex, m.k_confirm, file: file, line: line)
        XCTAssertEqual(AnyDisplayCrypto.confirmMAC(confirmKey: keys.confirm, who: "host", transcript: t).hex, m.auth_h,
                       file: file, line: line)
        XCTAssertEqual(AnyDisplayCrypto.confirmMAC(confirmKey: keys.confirm, who: "client", transcript: t).hex, m.auth_c,
                       file: file, line: line)

        var sender = FrameCipher(key: keys.hostToClient)
        let sealed = sender.seal(Ping(seq: 7, senderTimeUs: 123_456_789).frame)
        XCTAssertEqual(sealed.body.hex, m.encrypted_ping_h2c_seq0, file: file, line: line)
        XCTAssertEqual(sender.seq, 1)

        var receiver = FrameCipher(key: keys.hostToClient)
        let opened = try? receiver.open(Frame(.control, MessageType.ping, hex(m.encrypted_ping_h2c_seq0)))
        XCTAssertEqual(opened?.body.hex, v.ping_plaintext_body, file: file, line: line)
    }

    /// The handshake state machine, fed the vector client messages with the vector host key and nonce,
    /// emits byte-identical HELLO_H and AUTH_H and accepts the vector AUTH_C (mode 1).
    func testHostHandshakeMode1MatchesVectors() throws {
        let (_, h) = try keys()
        let hs = HostHandshake(hostID: Data(0xB0..<0xC0), hostName: "Mac", hostOS: "macOS",
                               secretForDevice: { _ in nil }, privateKey: h, hostNonce: hex(v.host_nonce))
        var ev = hs.receive(Frame(.control, MessageType.helloC, hex(v.hello_c_body)))
        guard case .send(let helloH)? = ev.first else { return XCTFail("no HELLO_H") }
        XCTAssertEqual(helloH.type, MessageType.helloH)
        XCTAssertEqual(helloH.body.hex, v.hello_h_body)

        ev = hs.receive(Frame(.control, MessageType.reveal, hex(v.reveal_body)))
        guard case .showSAS(let code)? = ev.first else { return XCTFail("no SAS") }
        XCTAssertEqual(code, v.sas)
        XCTAssertEqual(hs.stepTimeout, 120)

        XCTAssertTrue(hs.receive(Frame(.control, MessageType.sasOK)).isEmpty)
        ev = hs.userDecision(confirmed: true)
        XCTAssertEqual(ev.count, 2)
        guard case .send(let ok) = ev[0], case .send(let authH) = ev[1] else { return XCTFail() }
        XCTAssertEqual(ok.type, MessageType.sasOK)
        XCTAssertEqual(authH.type, MessageType.authH)
        XCTAssertEqual(authH.body.hex, v.mode1.auth_h)

        ev = hs.receive(Frame(.control, MessageType.authC, hex(v.mode1.auth_c)))
        guard case .enableEncryption(let send, let receive)? = ev.first else { return XCTFail("no encryption") }
        XCTAssertEqual(send.hex, v.mode1.k_h2c)
        XCTAssertEqual(receive.hex, v.mode1.k_c2h)
        XCTAssertEqual(hs.state, .awaitingPair)

        let secret = Data(repeating: 0x77, count: 32)
        ev = hs.receive(Frame(.control, MessageType.pair, secret))
        guard case .completed(let result)? = ev.first else { return XCTFail("not completed") }
        XCTAssertEqual(result.mode, .sas)
        XCTAssertEqual(result.pairSecret, secret)
        XCTAssertEqual(result.deviceName, "Phone")
        XCTAssertEqual(result.deviceID, Data(0xA0..<0xB0))
    }
}
